const e={"home.about.card.list.0":"தயாரிப்பு திசை ஆராய்ச்சி மற்றும் அங்கீகாரம் (நடப்பு)","home.about.card.list.1":"முக்கிய திறனை மேம்படுத்துதல்: பொறியியல் அமைப்பு / தரவுகள் மற்றும் சேவை திறன்கள் / அடிப்படையியல்","home.about.card.list.2":"மாதிரியாக்கம் மற்றும் விரைவு முறைமைகள்: யோசனை முதல் பயன்பாட்டுக்கூடிய பதிப்பு","home.about.card.list.3":"அனுமதி மற்றும் பாதுகாப்பு: தரவுப் பாதுகாப்பும் தனியுரிமை பாதுகாப்பும் மீது முக்கியத்துவம்","home.about.card.note":"வணிகத்தின் பரப்பளவு இன்னும் ஆராய்ச்சி நிலைமையில் உள்ளது...","home.about.card.title":"நாம் என்ன செய்கிறோம்?","home.about.desc.0":"நாங்கள் சுய ஆராய்ச்சியில் கவனம் செலுத்தும் நெட்வொர்க் தொழில்நுட்ப நிறுவனம்...","home.about.desc.1":"தற்போதைய வணிக வரம்பு இன்னும் தொடர்ந்த ஆராய்ச்சியில் உள்ளது...","home.about.hl.0.num":"சுயமாக உருவாக்கப்பட்ட முதல்","home.about.hl.0.text":"தன் சொந்த தயாரிப்புகள் மற்றும் வணிகத்தில் தொடர்ந்த முதலீடு.","home.about.hl.1.num":"தொடர்ச்சியான திருத்தம்","home.about.hl.1.text":"இயந்திரக் குவாலிட்டி, பராமரிப்பு மற்றும் அளவீட்டிற்கு முக்கியத்துவம் அளிக்கவும்.","home.about.hl.2.num":"தொடர்ந்து ஆராய்ந்து கொண்டிருக்கிறோம்","home.about.hl.2.text":"வணிகத் திசைகளின் இயக்கவியல் வளர்ச்சி மெதுவாக தெளிவான எல்லைகளை உருவாக்குகிறது.","home.about.title":"எங்களைப் பற்றி","home.brand.en":"TreeHouse Tech · Shanghai","home.common.city":"ஷாங்காய் · SHANGHAI","home.common.company":"上海树下小屋网络科技有限公司","home.common.email":"house@sxxw.site","home.common.email_mailto":"mailto:house@sxxw.site","home.contact.hint":"நாங்கள் தொடர்புகொள்வதற்காக, தயவுசெய்து மின்னஞ்சல் மூலம் தொடர்புகொள்ளவும்...","home.contact.label.city":"நகரம்","home.contact.label.company":"கம்பெனி பெயர்","home.contact.label.email":"மின்னஞ்சல்","home.contact.title":"தொடர்பு தகவல்","home.footer.legal":"© 2025 上海树下小屋网络科技有限公司","home.footer.links.about":"எங்களைப் பற்றி","home.footer.links.contact":"எங்களை தொடர்பு கொள்ளவும்","home.footer.links.home":"முகப்பு","home.footer.slogan":"சுயமாக ஆராய்ச்சி மற்றும் வளர்ச்சியில் கவனம் செலுத்துங்கள் · தொடர்ந்த ஆராய்ச்சி · நிலையான மாறுபாடு","home.hero.cta.about":"எங்களைப் பற்றி மேலும் அறிக","home.hero.cta.contact":"தொடர்பு தகவல்","home.hero.desc":"நாங்கள் சுய ஆராய்ச்சியில் கவனம் செலுத்தும் நெட்வொர்க் தொழில்நுட்ப நிறுவனம். நாங்கள் மதிப்புமிக்க தயாரிப்பு திசைகளை மற்றும் தொழில்நுட்ப செயலாக்க பாதைகளை தொடர்ந்து ஆராய்கிறோம், நீண்ட கால மறு திருத்தம் மற்றும் நிலையான வழங்கலுக்காக நோக்கமாகக் கொண்டுள்ளோம்.","home.hero.glass":'திசை ஆராய்ச்சி → பொறியியல் செயலாக்கம் → தயாரிப்பு மேம்பாடு <span class="dot"></span> நீண்டகாலம் / நிலையான வழங்கல்',"home.hero.meta.0.label":"தயாரிப்பு மற்றும் பொறியியல் மையமாக","home.hero.meta.0.num":"சுயமாக உருவாக்கப்பட்டது","home.hero.meta.1.label":"தொடர்ச்சியான திருத்தம் மற்றும் மேம்பாடு","home.hero.meta.1.num":"நீண்ட காலம்","home.hero.meta.2.label":"தரமும் ஒத்துழைப்பும் முக்கியத்துவம்","home.hero.meta.2.num":"திடமாக","home.hero.mini.foot":"* தற்போதைய அதிகாரப்பூர்வ வலைத்தளம் ஒரு அடிப்படை அறிமுகப் பக்கம் ஆகும், மற்றும் உள்ளடக்கம் வணிகம் முன்னேறுவதற்கேற்ப தொடர்ந்து புதுப்பிக்கப்படும்.","home.hero.mini.head":"குறிப்பு","home.hero.mini.main":"தொடர்ந்து வணிக திசைகளை ஆராய்ந்து கொண்டிருக்கிறோம்","home.hero.mini.stats.0.k":"மையம்","home.hero.mini.stats.0.v":"சுயமாக உருவாக்கப்பட்ட தயாரிப்பு","home.hero.mini.stats.1.k":"வடிவம்","home.hero.mini.stats.1.v":"மெதுவாக தெளிவுபடுத்தவும்","home.hero.mini.stats.2.k":"இசை","home.hero.mini.stats.2.v":"மறுபடியும் முன்னேற்றம்","home.hero.mini.stats.3.k":"இலக்கு","home.hero.mini.stats.3.v":"திடமான வளர்ச்சி","home.hero.title":'<span class="accent"> சுயாதீன ஆராய்ச்சி மற்றும் வளர்ச்சி </span> மற்றும் தயாரிப்பு ஆராய்ச்சி மீது கவனம் செலுத்துதல்',"home.html.lang":"ta","home.meta.description":"上海树下小屋网络科技有限公司 - சுயமாக ஆராய்ச்சி மற்றும் தயாரிப்பு ஆராய்ச்சியில் கவனம் செலுத்துகிறது","home.meta.title":"上海树下小屋网络科技有限公司","home.nav.about":"எங்களைப் பற்றி","home.nav.contact":"எங்களை தொடர்பு கொள்ளவும்","home.nav.home":"முகப்பு","home.nav.toggle":"மெனுவை விரிவாக்கவும்","home.noscript":"இந்த தளம் முழுமையான இடைமுக அனுபவத்திற்காக JavaScript ஐ தேவைப்படுகிறது (இயக்க மெனு, உருட்டும் விளைவுகள், மற்றும் பிற).","nav.apps":"ஆப் மையம்","nav.support":"ஆதரவு","apps.hero.eyebrow":"sxxw.site · ஆப் ஆதரவு மையம்","apps.hero.title":"ஒவ்வொரு ஆப்பும் தெளிவான வழிகாட்டுதலோடும், நீங்கள் கட்டுப்படுத்தும் தரவு எல்லைகளோடும் வருகிறது.","apps.hero.desc":"இங்கே தயாரிப்பு அறிமுகம், தொடக்க வழிகாட்டிகள், தனியுரிமைக் கொள்கை, விதிமுறைகள், தொழில்நுட்ப ஆதரவு ஆகியவற்றைக் காணலாம். நீங்கள் உண்மையில் பயன்படுத்தும் தளத்திற்கான பகுதியைப் படியுங்கள்.","apps.card.cta":"ஆப்பைப் பார்","apps.memoria.desc":"பிறந்தநாள்கள், ஆண்டுவிழாக்கள், கவுண்ட்டவுன்களைக் கண்காணியுங்கள். iOS பதிப்பு விருப்பத் தேர்வான தனிப்பட்ட iCloud ஒத்திசைவை ஆதரிக்கிறது; Huawei AppGallery-யின் Memoria பதிப்பு முழுவதுமாக சாதனத்திலேயே இயங்குகிறது.","apps.memoria.tag":"ஆண்டுவிழாக்கள் · நினைவூட்டல்கள்","apps.timetrails.desc":"தனியுரிமை-முதன்மை GPS பாதைப் பதிவு: பயணங்கள், உடற்பயிற்சிகள், சுற்றுலாக்களைத் தானாகப் பதிவு செய்கிறது, வரைபடத்தில் உங்கள் காலடித் தடங்களை வரைந்து, நீங்கள் சென்ற நகரங்களை ஒளிரச் செய்கிறது. பாதைகள் இயல்பாகச் சாதனத்திலேயே இருக்கும், விருப்பத் தேர்வான தனிப்பட்ட iCloud காப்புடன்.","apps.timetrails.tag":"GPS பாதைகள் · வழிகள்","apps.traceapp.desc":"பாதை, தூரம், வேகம், வேகக் கதி ஆகியவற்றைப் பதிவு செய்கிறது. கணக்கு இல்லை, உள்ளமைந்த விளம்பரங்களோ மூன்றாம் தரப்பு பகுப்பாய்வுகளோ இல்லை.","apps.traceapp.tag":"வழிகள் · புள்ளிவிவரம்","apps.footer.slogan":"தயாரிப்புகள் · வழிகாட்டிகள் · தனியுரிமை மற்றும் ஆதரவு","support.brand":"ஆதரவு","support.hero.eyebrow":"sxxw.site · ஆதரவு மையம்","support.hero.title":"உங்களுக்கு ஏற்ற வழியில் TreeHouse-ஐ தொடர்பு கொள்ளுங்கள்.","support.hero.desc":"TreeHouse ஆப்களுக்கான அனைத்து அதிகாரப்பூர்வ ஆதரவு சேனல்களும் ஒரே இடத்தில்: கருத்து, ஆப்-ஸ்டோர் மதிப்புரைகள், அதிகாரப்பூர்வ சமூகக் குழுக்கள். லோக்கல்-ஃபர்ஸ்ட், விளம்பரங்கள் இல்லை, மூன்றாம் தரப்பு கண்காணிப்பு இல்லை.","support.g1.title":"கருத்து","support.g1.note":"சிக்கல் ஏற்பட்டதா அல்லது யோசனை உள்ளதா? கீழேயுள்ள எந்த வழியிலும் எங்களைத் தொடர்பு கொள்ளுங்கள் — ஒவ்வொரு செய்தியையும் நாங்கள் படிக்கிறோம்.","support.g1.feedback.name":"ஆப்பினுள் கருத்து","support.g1.feedback.desc":"ஒவ்வொரு ஆப்பினுள்ளிருந்தே அனுப்புங்கள்; உங்கள் பதிப்பு, சாதனம், அமைப்புத் தகவல் தானாகவே இணைக்கப்படும், அதனால் நாங்கள் விரைவாக ஆராயலாம்.","support.g1.feedback.cta":"ஆப்களைப் பார்","support.g1.email.name":"மின்னஞ்சல் அனுப்பு","support.g1.email.desc":"முறையான கோரிக்கைகளுக்கும், தனியுரிமை அல்லது கணக்கு தொடர்பான விஷயங்களுக்கும் மின்னஞ்சலில் முழுமையான பதில் கிடைக்கும்.","support.g1.email.cta":"மின்னஞ்சல் அனுப்பு","support.g2.title":"ஆப்களை மதிப்பிடுங்கள் (ஒவ்வொரு ஆப்பிற்கும்)","support.g2.note":"பிடித்திருந்தால் நீங்கள் பயன்படுத்தும் ஸ்டோரில் மதிப்புரை எழுதுங்கள் — நாங்கள் பார்த்துப் பதிலளிக்கிறோம். உங்கள் ஆப்பிற்குப் பொருந்துவதைத் தட்டுங்கள்.","support.g2.cta.write":"மதிப்புரை எழுது","support.g2.cta.goto":"மதிப்புரைக்குச் செல்","support.g2.memoria.huawei.platform":"HarmonyOS · Huawei சாதனங்கள்","support.g3.title":"WeChat · QQ · Telegram குழுக்கள்","support.g3.note":"புதுப்பிப்புகளுக்கும் சக-பயனர்களின் உதவிக்கும் எங்கள் அதிகாரப்பூர்வ குழுக்களில் இணையுங்கள்: சீனாவில் WeChat / QQ, மற்ற இடங்களில் Telegram.","support.g3.wechat.name":"WeChat குழு","support.g3.wechat.desc":"தினசரி அரட்டையும் உதவியும். குழு நிரம்பும்போது புதிய QR குறியீடு வெளியிடப்படும்.","support.g3.qq.name":"QQ குழு","support.g3.qq.desc":"சீனாவில் உள்ள பயனர்களுக்கு; அதிக உறுப்பினர் வரம்பு.","support.g3.tg.name":"Telegram குழு","support.g3.tg.desc":"சர்வதேச பயனர்களுக்கான அரட்டையும் கேள்வி-பதிலும்.","support.g3.join":"இணை","support.pending":"விரைவில்","support.foot":"சரியான சேனலைக் கண்டறிய முடியவில்லையா? house@sxxw.site-க்கு மின்னஞ்சல் அனுப்புங்கள், நாங்கள் பதிலளிப்போம்.","support.footer.slogan":"கருத்து · ஆப்-ஸ்டோர் மதிப்புரைகள் · சமூகக் குழுக்கள்"};export{e as default};
